import { defineConfig, devices } from '@playwright/test';

// Runs against `make serve` (API + static export on :8765) with a fake camera and microphone.
// The fake microphone plays e2e/fixtures/think.wav (generated by global-setup with macOS `say`).
const fakeMedia = [
  '--use-fake-device-for-media-stream',
  '--use-fake-ui-for-media-stream',
  '--use-file-for-fake-audio-capture=e2e/fixtures/think.wav',
];

export default defineConfig({
  testDir: './e2e',
  globalSetup: './e2e/global-setup.ts',
  timeout: 90_000,
  expect: { timeout: 15_000 },
  retries: 0,
  reporter: [['list']],
  use: {
    baseURL: process.env.E2E_BASE_URL ?? 'http://127.0.0.1:8765',
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
    permissions: ['camera', 'microphone'],
    // Phone mode: the API demands the pairing token even from this machine (see global-setup).
    storageState: process.env.E2E_PAIRING_CODE ? 'e2e/.auth/device.json' : undefined,
  },
  projects: [
    {
      name: 'desktop',
      use: {
        ...devices['Desktop Chrome'],
        viewport: { width: 1280, height: 800 },
        launchOptions: { args: fakeMedia },
      },
    },
    {
      name: 'mobile',
      use: {
        ...devices['Desktop Chrome'],
        viewport: { width: 390, height: 844 },
        isMobile: true,
        hasTouch: true,
        launchOptions: { args: fakeMedia },
      },
    },
  ],
});
